/**
 *
 * Isolated mode gives an app its own theme. Its styles reach only its own elements, in the page and in
 * shadow roots, so several apps can share a page.
 *
 * @module isolation
 * @experimental
 *
 */
import type { PrimeVueIsolationOption } from '@primevue/core/config';

export interface IsolationOptions {
    /**
     * The app's key: letters, digits, `_` or `-`, up to 128 characters.
     *
     * Required with server rendering, so the server and the browser use the same key. Without it the
     * browser reuses the server-rendered `data-p-theme`, or picks a random key. A key another app on
     * the page already holds gets a `-2`, `-3` suffix.
     */
    key?: string;
}

/**
 * Turns on isolated mode.
 *
 * @param options The app's key.
 * @returns The value for the `isolation` option.
 * @throws TypeError when `key` is not valid.
 *
 * @example
 * app.use(PrimeVue, { theme, isolation: withIsolation({ key: 'shop' }) });
 *
 * @experimental
 */
export declare function withIsolation(options?: IsolationOptions): PrimeVueIsolationOption;

/**
 * A component style module, such as `ButtonStyle`.
 */
export interface IsolatedStyleModule {
    name?: string;
    css?: unknown;
    style?: unknown;
}

export interface IsolatedStyleSheetsOptions {
    /**
     * The same key the browser passes to `withIsolation`.
     */
    key: string;
    /**
     * The app's theme configuration. Without it only the components' own rules are rendered.
     */
    theme?: any;
    /**
     * The style modules of the components on the page, `BaseStyle` first.
     */
    styles?: IsolatedStyleModule[];
    /**
     * Attributes for every `<style>` element, such as `{ nonce }`.
     */
    props?: Record<string, unknown>;
    /**
     * Renders the native element reset, as the `preflight` option of the app does in the browser.
     *
     * @defaultValue false
     * @experimental
     */
    preflight?: boolean;
}

/**
 * Renders the `<style>` markup of an isolated app on the server. The browser takes it over when the
 * app hydrates.
 *
 * @param options The key, theme and style modules.
 * @returns The markup, split the same way as the default mode's style sheets.
 * @throws TypeError when `key` is missing or not valid.
 *
 * @example
 * const { stylesToTop, styles, themes } = getIsolatedStyleSheets({ key: 'shop', theme, styles: [BaseStyle, ButtonStyle] });
 *
 * @experimental
 */
export declare function getIsolatedStyleSheets(options: IsolatedStyleSheetsOptions): { stylesToTop: string; styles: string; themes: string };
